package com.areadarkener;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import javax.inject.Inject;
import javax.imageio.ImageIO;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PreMapLoad;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
	name = "Area Darkener",
	description = "A plugin for darkening any region in RuneScape. Created as an accessibility plugin but useful for all.",
	tags = {"dark", "area", "terrain", "accessibility", "wintertodt", "gwd", "huey", "vorkath", "visuals", "graphics", "recolor"}
)
public class AreaDarkenerPlugin extends Plugin
{
	private static final int NEXT_REFRESH_UNSET = -1;
	private static final int MAX_HSL = 0xFFFF;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AreaDarkenerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	private final Map<Integer, int[]> remappedHslByStrength = new HashMap<>();
	private final Set<Renderable> processedRenderables = Collections.newSetFromMap(new IdentityHashMap<>());
	private final Set<Model> processedModels = Collections.newSetFromMap(new IdentityHashMap<>());
	private final Map<Model, ModelSnapshot> modelSnapshots = new IdentityHashMap<>();
	private DarkAreaEntryStore entryStore;
	private AreaDarkenerPanel panel;
	private NavigationButton navigationButton;
	private int nextReloadTick = NEXT_REFRESH_UNSET;
	private OptionalInt latestRegionId = OptionalInt.empty();

	@Override
	protected void startUp()
	{
		entryStore = new DarkAreaEntryStore(configManager, gson);
		panel = new AreaDarkenerPanel(entryStore, this::currentRegionId, this::requestReload);
		navigationButton = NavigationButton.builder()
			.tooltip("Area Darkener")
			.icon(createIcon())
			.panel(panel)
			.priority(6)
			.build();
		clientToolbar.addNavigation(navigationButton);
		triggerMapReload(false);
	}

	@Override
	protected void shutDown()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
			panel = null;
		}
		triggerMapReload(true);
	}

	@Subscribe
	public void onPreMapLoad(PreMapLoad preMapLoad)
	{
		refreshLatestRegionIdLater();
		recolorMap(preMapLoad.getScene());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			refreshLatestRegionIdLater();
			return;
		}

		updateLatestRegionId(OptionalInt.empty());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AreaDarkenerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		requestReload();
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (panel != null && panel.isPanelShowing())
		{
			updateLatestRegionId();
		}
		if (nextReloadTick != NEXT_REFRESH_UNSET && client.getTickCount() >= nextReloadTick)
		{
			triggerMapReload(true);
			nextReloadTick = NEXT_REFRESH_UNSET;
		}
	}

	@Provides
	AreaDarkenerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AreaDarkenerConfig.class);
	}

	private void triggerMapReload(boolean restoreSnapshotsFirst)
	{
		clientThread.invokeLater(() ->
		{
			if (restoreSnapshotsFirst)
			{
				restoreSnapshots();
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	private void recolorMap(Scene scene)
	{
		clearRecolorState();
		Tile[][][] tiles = scene.isInstance() ? scene.getTiles() : scene.getExtendedTiles();
		if (tiles == null)
		{
			return;
		}

		for (Tile[][] zTiles : tiles)
		{
			for (Tile[] xTiles : zTiles)
			{
				for (Tile tile : xTiles)
				{
					AreaSettings settings = findAreaSettings(scene, tile);
					if (settings != null)
					{
						recolorTile(tile, settings.darknessStrength);
					}
				}
			}
		}
	}

	private AreaSettings findAreaSettings(Scene scene, Tile tile)
	{
		if (tile == null)
		{
			return null;
		}

		WorldPoint worldPoint = WorldPoint.fromLocalInstance(scene, tile.getLocalLocation(), tile.getPlane());
		if (worldPoint == null)
		{
			return null;
		}

		OptionalInt darkness = darknessForRegion(worldPoint.getRegionID());
		return darkness.isPresent() ? new AreaSettings(darkness.getAsInt()) : null;
	}

	OptionalInt darknessForRegion(int regionId)
	{
		if (entryStore != null)
		{
			OptionalInt entryDarkness = entryStore.findDarknessForRegion(regionId);
			if (entryDarkness.isPresent())
			{
				return entryDarkness;
			}
		}

		return config.globalDarkenEnabled() ? OptionalInt.of(config.globalDarkenStrength()) : OptionalInt.empty();
	}

	void requestReload()
	{
		clientThread.invokeLater(() ->
		{
			clearRecolorState();
			nextReloadTick = client.getTickCount() + 1;
		});
	}

	OptionalInt currentRegionId()
	{
		return latestRegionId;
	}

	private void refreshLatestRegionIdLater()
	{
		clientThread.invokeLater(() -> updateLatestRegionId());
	}

	private void updateLatestRegionId()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			updateLatestRegionId(OptionalInt.empty());
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			updateLatestRegionId(OptionalInt.empty());
			return;
		}

		WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation());
		updateLatestRegionId(worldPoint == null ? OptionalInt.empty() : OptionalInt.of(worldPoint.getRegionID()));
	}

	private void updateLatestRegionId(OptionalInt regionId)
	{
		if (sameRegion(latestRegionId, regionId))
		{
			return;
		}

		latestRegionId = regionId;
		if (panel != null)
		{
			panel.rebuild();
		}
	}

	private static boolean sameRegion(OptionalInt first, OptionalInt second)
	{
		return first.isPresent() == second.isPresent()
			&& (!first.isPresent() || first.getAsInt() == second.getAsInt());
	}

	private void recolorTile(Tile tile, int darknessStrength)
	{
		Tile current = tile;
		while (current != null)
		{
			recolorTilePaint(current.getSceneTilePaint(), darknessStrength);
			recolorTileModel(current.getSceneTileModel(), darknessStrength);
			recolorGroundObject(current.getGroundObject(), darknessStrength);
			recolorGameObjects(current.getGameObjects(), darknessStrength);
			recolorRenderable(current.getDecorativeObject() == null ? null : current.getDecorativeObject().getRenderable(), darknessStrength);
			recolorRenderable(current.getDecorativeObject() == null ? null : current.getDecorativeObject().getRenderable2(), darknessStrength);
			recolorRenderable(current.getWallObject() == null ? null : current.getWallObject().getRenderable1(), darknessStrength);
			recolorRenderable(current.getWallObject() == null ? null : current.getWallObject().getRenderable2(), darknessStrength);
			current = current.getBridge();
		}
	}

	private void recolorTilePaint(SceneTilePaint paint, int darknessStrength)
	{
		if (paint == null || paint.getTexture() != -1)
		{
			return;
		}

		paint.setNwColor(remappedHsl(paint.getNwColor(), darknessStrength));
		paint.setNeColor(remappedHsl(paint.getNeColor(), darknessStrength));
		paint.setSwColor(remappedHsl(paint.getSwColor(), darknessStrength));
		paint.setSeColor(remappedHsl(paint.getSeColor(), darknessStrength));
	}

	private void recolorTileModel(SceneTileModel model, int darknessStrength)
	{
		if (model == null)
		{
			return;
		}

		adjustColors(model.getTriangleColorA(), model.getTriangleTextureId(), darknessStrength);
		adjustColors(model.getTriangleColorB(), model.getTriangleTextureId(), darknessStrength);
		adjustColors(model.getTriangleColorC(), model.getTriangleTextureId(), darknessStrength);
	}

	private void recolorGroundObject(GroundObject groundObject, int darknessStrength)
	{
		recolorRenderable(groundObject == null ? null : groundObject.getRenderable(), darknessStrength);
	}

	private void recolorGameObjects(GameObject[] gameObjects, int darknessStrength)
	{
		if (gameObjects == null)
		{
			return;
		}

		for (GameObject gameObject : gameObjects)
		{
			recolorRenderable(gameObject == null ? null : gameObject.getRenderable(), darknessStrength);
		}
	}

	private void recolorRenderable(Renderable renderable, int darknessStrength)
	{
		if (!(renderable instanceof Model) || !processedRenderables.add(renderable))
		{
			return;
		}

		Model model = (Model) renderable;
		if (!processedModels.add(model))
		{
			return;
		}

		modelSnapshots.computeIfAbsent(model, ModelSnapshot::new);
		adjustColors(model.getFaceColors1(), null, darknessStrength);
		adjustColors(model.getFaceColors2(), null, darknessStrength);
		adjustColors(model.getFaceColors3(), null, darknessStrength);
		adjustShortColors(model.getUnlitFaceColors(), darknessStrength);
	}

	private void adjustColors(int[] colors, int[] textures, int darknessStrength)
	{
		if (colors == null)
		{
			return;
		}

		for (int i = 0; i < colors.length; i++)
		{
			if (textures == null || textures.length <= i || textures[i] == -1)
			{
				colors[i] = remappedHsl(colors[i], darknessStrength);
			}
		}
	}

	private void adjustShortColors(short[] colors, int darknessStrength)
	{
		if (colors == null)
		{
			return;
		}

		for (int i = 0; i < colors.length; i++)
		{
			colors[i] = (short) remappedHsl(colors[i] & MAX_HSL, darknessStrength);
		}
	}

	private int remappedHsl(int hsl, int darknessStrength)
	{
		if (hsl < 0 || hsl > MAX_HSL)
		{
			return hsl;
		}

		int[] remappedHsl = remappedHslByStrength.computeIfAbsent(darknessStrength, this::buildColorMap);
		return remappedHsl[hsl];
	}

	private int[] buildColorMap(int darknessStrength)
	{
		int[] remappedHsl = new int[MAX_HSL + 1];
		for (int hsl = 0; hsl < remappedHsl.length; hsl++)
		{
			remappedHsl[hsl] = HslDarkener.darkenPackedHsl(hsl, darknessStrength);
		}
		return remappedHsl;
	}

	private void clearRecolorState()
	{
		processedRenderables.clear();
		processedModels.clear();
		remappedHslByStrength.clear();
		restoreSnapshots();
	}

	private void restoreSnapshots()
	{
		for (Map.Entry<Model, ModelSnapshot> entry : modelSnapshots.entrySet())
		{
			entry.getValue().restore(entry.getKey());
		}
		modelSnapshots.clear();
	}

	private static void restoreArray(int[] target, int[] source)
	{
		if (target != null && source != null && target.length == source.length)
		{
			System.arraycopy(source, 0, target, 0, source.length);
		}
	}

	private static void restoreArray(short[] target, short[] source)
	{
		if (target != null && source != null && target.length == source.length)
		{
			System.arraycopy(source, 0, target, 0, source.length);
		}
	}

	private static BufferedImage createIcon()
	{
		try (InputStream inputStream = AreaDarkenerPlugin.class.getResourceAsStream("area-darkener-icon.png"))
		{
			if (inputStream != null)
			{
				return ImageIO.read(inputStream);
			}
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Unable to load Area Darkener icon", ex);
		}

		throw new IllegalStateException("Area Darkener icon resource is missing");
	}

	private static final class AreaSettings
	{
		private final int darknessStrength;

		private AreaSettings(int darknessStrength)
		{
			this.darknessStrength = darknessStrength;
		}
	}

	private static final class ModelSnapshot
	{
		private final int[] faceColors1;
		private final int[] faceColors2;
		private final int[] faceColors3;
		private final short[] unlitFaceColors;

		private ModelSnapshot(Model model)
		{
			faceColors1 = model.getFaceColors1() == null ? null : model.getFaceColors1().clone();
			faceColors2 = model.getFaceColors2() == null ? null : model.getFaceColors2().clone();
			faceColors3 = model.getFaceColors3() == null ? null : model.getFaceColors3().clone();
			unlitFaceColors = model.getUnlitFaceColors() == null ? null : model.getUnlitFaceColors().clone();
		}

		private void restore(Model model)
		{
			restoreArray(model.getFaceColors1(), faceColors1);
			restoreArray(model.getFaceColors2(), faceColors2);
			restoreArray(model.getFaceColors3(), faceColors3);
			restoreArray(model.getUnlitFaceColors(), unlitFaceColors);
		}
	}
}

package com.areadarkener;

final class HslDarkener
{
	private static final int MAX_HSL = 0xFFFF;
	private static final int HSL_HUE_SHIFT = 10;
	private static final int HSL_SATURATION_SHIFT = 7;
	private static final int HSL_HUE_MASK = 0x3F;
	private static final int HSL_SATURATION_MASK = 0x7;
	private static final int HSL_LIGHTNESS_MASK = 0x7F;
	private static final int HSL_HIDDEN_COLOR = 12345678;

	private HslDarkener()
	{
	}

	static int darkenPackedHsl(int packedHsl, int darknessStrength)
	{
		if (packedHsl == HSL_HIDDEN_COLOR || packedHsl < 0 || packedHsl > MAX_HSL)
		{
			return packedHsl;
		}

		int clampedStrength = Math.max(0, Math.min(100, darknessStrength));
		double scale = (100.0 - clampedStrength) / 100.0;
		int hue = (packedHsl >> HSL_HUE_SHIFT) & HSL_HUE_MASK;
		int saturation = (packedHsl >> HSL_SATURATION_SHIFT) & HSL_SATURATION_MASK;
		int lightness = packedHsl & HSL_LIGHTNESS_MASK;
		int newLightness = Math.max(1, Math.min(HSL_LIGHTNESS_MASK, (int) Math.ceil(scale * lightness)));

		return (hue << HSL_HUE_SHIFT) | (saturation << HSL_SATURATION_SHIFT) | newLightness;
	}
}

package com.areadarkener;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.Set;
import net.runelite.client.config.ConfigManager;

final class DarkAreaEntryStore
{
	static final String CONFIG_KEY = "areaEntries";
	static final int DEFAULT_AREA_STRENGTH = 50;
	private static final Type ENTRY_LIST_TYPE = new TypeToken<List<DarkAreaEntry>>()
	{
	}.getType();

	private final Gson gson;
	private final Storage storage;
	private List<DarkAreaEntry> entries;

	DarkAreaEntryStore(ConfigManager configManager, Gson gson)
	{
		this(new ConfigManagerStorage(configManager), gson);
	}

	DarkAreaEntryStore(Storage storage, Gson gson)
	{
		this.storage = storage;
		this.gson = gson;
		this.entries = loadEntries();
	}

	List<DarkAreaEntry> getEntries()
	{
		return entries;
	}

	void saveEntries(List<DarkAreaEntry> entries)
	{
		this.entries = sanitize(entries);
		storage.save(gson.toJson(this.entries, ENTRY_LIST_TYPE));
	}

	Optional<DarkAreaEntry> findEntryContainingRegion(int regionId)
	{
		return entries.stream()
			.filter(entry -> entry.containsRegion(regionId))
			.findFirst();
	}

	OptionalInt findDarknessForRegion(int regionId)
	{
		return entries.stream()
			.filter(DarkAreaEntry::isEnabled)
			.filter(entry -> entry.containsRegion(regionId))
			.mapToInt(DarkAreaEntry::getDarkness)
			.findFirst();
	}

	String nextEntryName()
	{
		int index = 1;
		while (containsEntryName("My Entry " + index))
		{
			index++;
		}
		return "My Entry " + index;
	}

	boolean addCurrentRegionToEntry(DarkAreaEntry entry, int regionId)
	{
		if (regionId <= 0 || findEntryContainingRegion(regionId).isPresent())
		{
			return false;
		}

		List<Integer> regionIds = new ArrayList<>(entry.getRegionIds());
		regionIds.add(regionId);
		entry.setRegionIds(regionIds);
		saveEntries(entries);
		return true;
	}

	DarkAreaEntry createCurrentRegionEntry(int regionId)
	{
		return new DarkAreaEntry(nextEntryName(), List.of(regionId), DEFAULT_AREA_STRENGTH, true);
	}

	private List<DarkAreaEntry> loadEntries()
	{
		String json = storage.load();
		if (json == null || json.trim().isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			List<DarkAreaEntry> loaded = gson.fromJson(json, ENTRY_LIST_TYPE);
			if (loaded == null)
			{
				return new ArrayList<>();
			}

			List<DarkAreaEntry> sanitized = sanitize(loaded);
			return sanitized;
		}
		catch (RuntimeException ex)
		{
			return new ArrayList<>();
		}
	}

	private List<DarkAreaEntry> sanitize(List<DarkAreaEntry> unsanitized)
	{
		List<DarkAreaEntry> sanitized = new ArrayList<>();
		Set<Integer> seenRegionIds = new HashSet<>();
		for (DarkAreaEntry entry : unsanitized)
		{
			if (entry == null)
			{
				continue;
			}

			List<Integer> regionIds = new ArrayList<>();
			if (entry.getRegionIds() == null)
			{
				continue;
			}

			for (Integer regionId : entry.getRegionIds())
			{
				if (regionId != null && regionId > 0 && seenRegionIds.add(regionId))
				{
					regionIds.add(regionId);
				}
			}

			if (regionIds.isEmpty())
			{
				continue;
			}

			String name = entry.getName() == null || entry.getName().trim().isEmpty() ? nextFallbackName(sanitized.size()) : entry.getName().trim();
			sanitized.add(new DarkAreaEntry(name, regionIds, clamp(entry.getDarkness()), entry.isEnabled()));
		}
		return sanitized;
	}

	private boolean containsEntryName(String name)
	{
		return entries.stream().anyMatch(entry -> entry.getName().equals(name));
	}

	private static int clamp(int value)
	{
		return Math.max(0, Math.min(100, value));
	}

	private static String nextFallbackName(int index)
	{
		return "My Entry " + (index + 1);
	}

	interface Storage
	{
		String load();

		void save(String value);
	}

	private static final class ConfigManagerStorage implements Storage
	{
		private final ConfigManager configManager;

		private ConfigManagerStorage(ConfigManager configManager)
		{
			this.configManager = configManager;
		}

		@Override
		public String load()
		{
			return configManager.getConfiguration(AreaDarkenerConfig.GROUP, CONFIG_KEY);
		}

		@Override
		public void save(String value)
		{
			configManager.setConfiguration(AreaDarkenerConfig.GROUP, CONFIG_KEY, value);
		}
	}
}

package com.areadarkener;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(AreaDarkenerConfig.GROUP)
public interface AreaDarkenerConfig extends Config
{
	String GROUP = "areadarkener";

	@ConfigItem(
		keyName = "globalDarkenEnabled",
		name = "Global Darken",
		description = "Darken every region that is not handled by an enabled Area Darkener entry",
		position = 0
	)
	default boolean globalDarkenEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "globalDarkenStrength",
		name = "Global Darken Strength",
		description = "How strongly to darken regions handled by Global Darken",
		position = 1
	)
	@Range(min = 0, max = 100)
	default int globalDarkenStrength()
	{
		return 50;
	}
}

package com.areadarkener;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

final class DarkAreaPreset
{
	private static final List<DarkAreaPreset> PRESETS = Collections.unmodifiableList(Arrays.asList(
		new DarkAreaPreset("Asgarnian Ice Dungeon", 11925),
		new DarkAreaPreset("Fremennik Hunter Area", 10810, 10811),
		new DarkAreaPreset("God Wars Dungeon", 11345, 11346, 11347, 11601, 11602, 11603),
		new DarkAreaPreset("Hueycoatl", 5939),
		new DarkAreaPreset("Penguin Agility Course", 10559),
		new DarkAreaPreset("Phantom Muspah", 11330),
		new DarkAreaPreset("Vorkath", 9023),
		new DarkAreaPreset("Weiss", 11325),
		new DarkAreaPreset("Wintertodt", 6461, 6462)
	));

	private final String name;
	private final List<Integer> regionIds;

	private DarkAreaPreset(String name, Integer... regionIds)
	{
		this.name = name;
		this.regionIds = Collections.unmodifiableList(Arrays.asList(regionIds));
	}

	static List<DarkAreaPreset> getPresets()
	{
		return PRESETS;
	}

	String getName()
	{
		return name;
	}

	List<Integer> getRegionIds()
	{
		return regionIds;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.areadarkener;

import java.util.ArrayList;
import java.util.List;

final class DarkAreaEntry
{
	private String name;
	private List<Integer> regionIds;
	private int darkness;
	private boolean enabled;

	DarkAreaEntry()
	{
		this("", new ArrayList<>(), 45, true);
	}

	DarkAreaEntry(String name, List<Integer> regionIds, int darkness, boolean enabled)
	{
		this.name = name;
		this.regionIds = new ArrayList<>(regionIds);
		this.darkness = darkness;
		this.enabled = enabled;
	}

	String getName()
	{
		return name;
	}

	void setName(String name)
	{
		this.name = name;
	}

	List<Integer> getRegionIds()
	{
		return regionIds;
	}

	void setRegionIds(List<Integer> regionIds)
	{
		this.regionIds = new ArrayList<>(regionIds);
	}

	int getDarkness()
	{
		return darkness;
	}

	void setDarkness(int darkness)
	{
		this.darkness = darkness;
	}

	boolean isEnabled()
	{
		return enabled;
	}

	void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	boolean containsRegion(int regionId)
	{
		return regionIds.contains(regionId);
	}
}

package com.areadarkener;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.HierarchyEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

final class AreaDarkenerPanel extends PluginPanel
{
	private static final Color SECTION_BACKGROUND = new Color(35, 35, 35);
	private static final Color CARD_BACKGROUND = new Color(43, 43, 43);

	private final DarkAreaEntryStore store;
	private final Supplier<OptionalInt> currentRegionSupplier;
	private final Runnable changedCallback;
	private final JPanel mainPanel;
	private final JScrollPane scrollPane;
	private volatile boolean panelShowing;
	private DarkAreaEntry editingEntry;

	AreaDarkenerPanel(
		DarkAreaEntryStore store,
		Supplier<OptionalInt> currentRegionSupplier,
		Runnable changedCallback
	)
	{
		super(false);
		this.store = store;
		this.currentRegionSupplier = currentRegionSupplier;
		this.changedCallback = changedCallback;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		addHierarchyListener(event ->
		{
			if ((event.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0)
			{
				panelShowing = isShowing();
			}
		});

		mainPanel = new FixedWidthPanel();
		mainPanel.setLayout(new BoxLayout(mainPanel, BoxLayout.Y_AXIS));
		mainPanel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		mainPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel northPanel = new FixedWidthPanel();
		northPanel.setLayout(new BorderLayout());
		northPanel.add(mainPanel, BorderLayout.NORTH);

		scrollPane = new JScrollPane(northPanel);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		add(scrollPane, BorderLayout.CENTER);

		rebuild();
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(PANEL_WIDTH + SCROLLBAR_WIDTH, super.getPreferredSize().height);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(PANEL_WIDTH + SCROLLBAR_WIDTH, 0);
	}

	void rebuild()
	{
		mainPanel.removeAll();

		mainPanel.add(sectionTitle("Current region"));
		mainPanel.add(currentRegionPanel(null));

		mainPanel.add(Box.createVerticalStrut(8));
		mainPanel.add(sectionTitle("Presets"));
		mainPanel.add(presetsPanel());

		mainPanel.add(Box.createVerticalStrut(8));
		mainPanel.add(sectionTitle("My Areas"));
		if (store.getEntries().isEmpty())
		{
			mainPanel.add(mutedLabel("No areas yet."));
		}
		for (DarkAreaEntry entry : store.getEntries())
		{
			mainPanel.add(entryCard(entry));
			mainPanel.add(Box.createVerticalStrut(8));
		}

		mainPanel.revalidate();
		mainPanel.repaint();
		scrollPane.getViewport().revalidate();
		scrollPane.getViewport().repaint();
		revalidate();
		repaint();
	}

	boolean isPanelShowing()
	{
		return panelShowing;
	}

	private JPanel presetsPanel()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JComboBox<DarkAreaPreset> presets = new JComboBox<>(DarkAreaPreset.getPresets().toArray(new DarkAreaPreset[0]));
		presets.setMaximumSize(new Dimension(Integer.MAX_VALUE, presets.getPreferredSize().height));
		JButton add = new JButton("Add");
		add.setAlignmentX(Component.CENTER_ALIGNMENT);
		updatePresetAddButton(add, (DarkAreaPreset) presets.getSelectedItem());
		presets.addActionListener(event -> updatePresetAddButton(add, (DarkAreaPreset) presets.getSelectedItem()));
		add.addActionListener(event ->
		{
			DarkAreaPreset preset = (DarkAreaPreset) presets.getSelectedItem();
			if (preset == null)
			{
				return;
			}

			List<Integer> regionIds = missingRegionIds(preset.getRegionIds());
			if (!regionIds.isEmpty())
			{
				List<DarkAreaEntry> entries = new ArrayList<>(store.getEntries());
				entries.add(new DarkAreaEntry(preset.getName(), regionIds, DarkAreaEntryStore.DEFAULT_AREA_STRENGTH, true));
				saveAndRefresh(entries);
			}
		});

		panel.add(presets);
		panel.add(Box.createVerticalStrut(4));
		panel.add(add);
		return panel;
	}

	private void updatePresetAddButton(JButton add, DarkAreaPreset preset)
	{
		Optional<DarkAreaEntry> duplicate = preset == null ? Optional.empty() : firstDuplicate(preset.getRegionIds());
		add.setEnabled(!duplicate.isPresent());
		add.setToolTipText(duplicate.map(entry -> "Region already added to \"" + entry.getName() + "\"").orElse(null));
	}

	private JPanel currentRegionPanel(DarkAreaEntry targetEntry)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setBackground(SECTION_BACKGROUND);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		JButton add = new JButton(targetEntry == null ? "Add current region" : "+ Current Region");
		add.setAlignmentX(Component.CENTER_ALIGNMENT);
		JLabel helper = targetEntry == null ? mutedLabel("Create new entry for region") : null;
		OptionalInt currentRegion = currentRegionSupplier.get();
		if (!currentRegion.isPresent())
		{
			add.setEnabled(false);
			if (targetEntry == null)
			{
				helper = mutedLabel("Current region unavailable.");
			}
		}
		else
		{
			Optional<DarkAreaEntry> duplicate = store.findEntryContainingRegion(currentRegion.getAsInt());
			if (duplicate.isPresent())
			{
				add.setEnabled(false);
				if (targetEntry == null)
				{
					helper = mutedLabel("Region already added to \"" + duplicate.get().getName() + "\"");
				}
			}
		}

		add.addActionListener(event ->
		{
			OptionalInt region = currentRegionSupplier.get();
			if (!region.isPresent())
			{
				return;
			}

			if (targetEntry == null)
			{
				List<DarkAreaEntry> entries = new ArrayList<>(store.getEntries());
				entries.add(store.createCurrentRegionEntry(region.getAsInt()));
				saveAndRefresh(entries);
			}
			else if (store.addCurrentRegionToEntry(targetEntry, region.getAsInt()))
			{
				changedCallback.run();
				rebuild();
			}
		});

		panel.add(targetEntry == null ? add : centeredButtonPanel(add));
		if (targetEntry == null && helper != null)
		{
			helper.setAlignmentX(Component.CENTER_ALIGNMENT);
			panel.add(Box.createVerticalStrut(4));
			panel.add(helper);
		}
		return panel;
	}

	private JPanel entryCard(DarkAreaEntry entry)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setBackground(CARD_BACKGROUND);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JPanel header = rowPanel();
		JCheckBox enabled = new JCheckBox("", entry.isEnabled());
		enabled.setToolTipText("Enable area");
		enabled.addActionListener(event ->
		{
			entry.setEnabled(enabled.isSelected());
			saveAndRefresh(store.getEntries());
		});
		Component title = titleComponent(entry);
		JButton edit = new JButton("\u270E");
		edit.setToolTipText("Edit title");
		edit.addActionListener(event ->
		{
			editingEntry = entry;
			rebuild();
		});
		JButton remove = new JButton("\uD83D\uDDD1");
		remove.setToolTipText("Remove entry");
		remove.addActionListener(event ->
		{
			List<DarkAreaEntry> entries = new ArrayList<>(store.getEntries());
			entries.remove(entry);
			saveAndRefresh(entries);
		});
		header.add(enabled, constraints(0, 0, 0.0));
		header.add(title, constraints(1, 0, 1.0));
		header.add(edit, constraints(2, 0, 0.0));
		header.add(remove, constraints(3, 0, 0.0));
		card.add(header);
		card.add(Box.createVerticalStrut(6));

		card.add(strengthPanel(entry));
		card.add(Box.createVerticalStrut(6));

		card.add(new JLabel("IDs"));
		for (Integer regionId : entry.getRegionIds())
		{
			card.add(regionRow(entry, regionId, currentRegionSupplier.get()));
		}
		card.add(entryCurrentRegionButton(entry));
		return card;
	}

	private JPanel strengthPanel(DarkAreaEntry entry)
	{
		JPanel controls = rowPanel();
		JSpinner darkness = new JSpinner(new SpinnerNumberModel(entry.getDarkness(), 0, 100, 1));
		darkness.addChangeListener(event ->
		{
			entry.setDarkness((Integer) darkness.getValue());
			saveAndRefresh(store.getEntries());
		});

		controls.add(new JLabel("Strength"), constraints(0, 0, 1.0));
		controls.add(darkness, constraints(1, 0, 0.0));
		return controls;
	}

	private JPanel entryCurrentRegionButton(DarkAreaEntry entry)
	{
		JButton add = new JButton("+ Current Region");
		add.setAlignmentX(Component.CENTER_ALIGNMENT);
		OptionalInt currentRegion = currentRegionSupplier.get();
		if (!currentRegion.isPresent() || store.findEntryContainingRegion(currentRegion.getAsInt()).isPresent())
		{
			add.setEnabled(false);
		}
		add.addActionListener(event ->
		{
			OptionalInt region = currentRegionSupplier.get();
			if (region.isPresent() && store.addCurrentRegionToEntry(entry, region.getAsInt()))
			{
				changedCallback.run();
				rebuild();
			}
		});
		return centeredButtonPanel(add);
	}

	private Component titleComponent(DarkAreaEntry entry)
	{
		if (entry == editingEntry)
		{
			JTextField name = new JTextField(entry.getName());
			name.addActionListener(event ->
			{
				saveName(entry, name.getText());
				editingEntry = null;
				rebuild();
			});
			name.addFocusListener(new FocusAdapter()
			{
				@Override
				public void focusLost(FocusEvent event)
				{
					saveName(entry, name.getText());
					editingEntry = null;
					rebuild();
				}
			});
			return name;
		}

		JLabel label = new JLabel(entry.getName());
		label.setFont(label.getFont().deriveFont(Font.BOLD));
		return label;
	}

	private JPanel regionRow(DarkAreaEntry entry, Integer regionId, OptionalInt currentRegion)
	{
		JPanel row = rowPanel();
		boolean isCurrent = currentRegion.isPresent() && currentRegion.getAsInt() == regionId;
		row.add(new JLabel(regionId + (isCurrent ? " (current)" : "")), constraints(0, 0, 1.0));
		JButton remove = new JButton("-");
		remove.setToolTipText("Remove region ID");
		remove.addActionListener(event ->
		{
			List<Integer> ids = new ArrayList<>(entry.getRegionIds());
			ids.remove(regionId);
			entry.setRegionIds(ids);
			saveAndRefresh(store.getEntries());
		});
		row.add(remove, constraints(1, 0, 0.0));
		return row;
	}

	private void saveName(DarkAreaEntry entry, String value)
	{
		String name = value == null || value.trim().isEmpty() ? store.nextEntryName() : value.trim();
		if (!name.equals(entry.getName()))
		{
			entry.setName(name);
			saveAndRefresh(store.getEntries());
		}
	}

	private Optional<DarkAreaEntry> firstDuplicate(List<Integer> regionIds)
	{
		return regionIds.stream()
			.map(store::findEntryContainingRegion)
			.filter(Optional::isPresent)
			.map(Optional::get)
			.findFirst();
	}

	private List<Integer> missingRegionIds(List<Integer> regionIds)
	{
		List<Integer> missing = new ArrayList<>();
		for (Integer regionId : regionIds)
		{
			if (!store.findEntryContainingRegion(regionId).isPresent())
			{
				missing.add(regionId);
			}
		}
		return missing;
	}

	private void saveAndRefresh(List<DarkAreaEntry> entries)
	{
		store.saveEntries(entries);
		changedCallback.run();
		rebuild();
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(label.getFont().deriveFont(Font.BOLD));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel mutedLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(Color.GRAY);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JPanel centeredButtonPanel(JButton button)
	{
		JPanel panel = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		panel.add(button);
		return panel;
	}

	private static JPanel rowPanel()
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		return panel;
	}

	private static GridBagConstraints constraints(int x, int y, double weightX)
	{
		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = x;
		constraints.gridy = y;
		constraints.weightx = weightX;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.insets = new Insets(1, 1, 1, 1);
		return constraints;
	}

	private static final class FixedWidthPanel extends JPanel
	{
		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(PANEL_WIDTH, super.getPreferredSize().height);
		}

		@Override
		public Dimension getMinimumSize()
		{
			return new Dimension(PANEL_WIDTH, super.getMinimumSize().height);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(PANEL_WIDTH, super.getMaximumSize().height);
		}
	}
}
